import styled from '@emotion/styled';
import { Button } from 'components/UI';

type AlertType =
  | 'AI'
  | 'info'
  | 'success'
  | 'warning'
  | 'error'
  | 'neutral';

interface ActionButtonStyledProps {
  $alertType?: AlertType;
}

const interactiveButtonStyles = {
  AI: {
    color: '#006edb',
    hoverOutline: '#a1d0ff',
    activeBg: '#006edb',
    activeOutline: '#006edb',
  },
  info: {
    color: '#006edb',
    hoverOutline: '#a1d0ff',
    activeBg: '#006edb',
    activeOutline: '#006edb',
  },
  success: {
    color: '#009900',
    hoverOutline: '#99e699',
    activeBg: '#009900',
    activeOutline: '#99e699',
  },
  warning: {
    color: '#d47300',
    hoverOutline: '#ffd499',
    activeBg: '#d47300',
    activeOutline: '#ffd499',
  },
  error: {
    color: '#d62222',
    hoverOutline: '#fca5a5',
    activeBg: '#d62222',
    activeOutline: '#fca5a5',
  },
  neutral: {
    color: '#141414',
    hoverOutline: '#14141429',
    activeBg: '#141414',
    activeOutline: '#14141429',
  },
} as const;

export const ActionButtonStyled = styled(Button, {
  shouldForwardProp: (propName) => propName !== '$alertType',
})<ActionButtonStyledProps>(({ $alertType }) => {
  const variantStyles =
    $alertType != null ? interactiveButtonStyles[$alertType] : undefined;

  return {
    '&&': {
      borderRadius: '512px',
      color: variantStyles?.color ?? '#006edb',
      border: 'none',
      outline: '1px solid',
      fontWeight: '400',
      lineHeight: '20px',
      padding: '4px 8px',
      fontSize: '14px',
      height: 'min-content',
      borderWidth: '1px',
      textWrap: 'nowrap',
      backgroundColor: '#fff',
      boxShadow: 'none',
      ...(variantStyles && {
        '&:hover': {
          outlineColor: variantStyles.hoverOutline,
          backgroundColor: '#fff',
        },
        '&:active': {
          backgroundColor: variantStyles.activeBg,
          outlineColor: variantStyles.activeOutline,
          color: '#fff',
        },
      }),
    },
  };
});

ActionButtonStyled.defaultProps = {
  variant: 'secondary',
};
